}

kprobe:blk_account_io_done
/ @start[arg0] /
{
    $lat_us = (nsecs - @start[arg0]) / 1000;

    // 3. 使用直方图而非每事件打印
    @latency_us = hist($lat_us);
    @latency_by_comm[comm] = hist($lat_us);

